import java.util.ArrayList;
import java.util.HashSet;
import java.util.Scanner;

/**
 * Created by Pranav ps on 04-09-2017.
 */
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if(n <= 11){
            long[][] points = new long[n][5];

            for(int i = 0 ; i < n; i++){
                for (int j = 0; j < 5; j++) {
                    points[i][j] = sc.nextLong();
                }
            }

            long[][][] vectors = new long[n][n][5];
            for(int i = 0; i < n; i++){
                for(int j = 0; j < n; j++){
                    for (int k = 0; k < 5; k++) {
                        vectors[i][j][k] = points[j][k] - points[i][k];
                    }
                }
            }

            HashSet<Integer> list = new HashSet<>();

            for(int i = 0; i < n; i++){
                boolean flag = false;
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if(!equal(vectors[i][j],vectors[i][k]) && dot(vectors[i][j],vectors[i][k])){
                            list.add(i+1);
                            flag = true;
                            break;
                        }
                    }
                    if(flag)
                        break;
                }
            }

            System.out.println(n - list.size());
            for(int i = 0; i < n; i++){
                if(!list.contains(i+1))
                    System.out.println(i+1);
            }
        }
        else{
            System.out.println(0);
        }
    }
    private static boolean equal(long[] a, long[] b){
        boolean res = true;
        for(int i = 0 ; i < 5; i++){
            res &= a[i]==b[i];
        }
        return res;
    }
    private static boolean dot(long[] a, long[] b){
        long res = 0;
        for(int i = 0 ; i < 5; i++){
            res += a[i]*b[i];
        }

        return res>0;
    }
}

